solution.solution.cpp:
#include <cstdint>

struct Distance
{
    double metres{};
};

constexpr Distance operator""_m(long double value)
{
    return Distance{ static_cast<double>(value) };
}

constexpr Distance operator""_m(unsigned long long value)
{
    return Distance{ static_cast<double>(value) };
}

constexpr Distance operator""_km(long double value)
{
    return Distance{ static_cast<double>(value) * 1000.0 };
}

constexpr Distance operator""_km(unsigned long long value)
{
    return Distance{ static_cast<double>(value) * 1000.0 };
}

constexpr Distance operator+(Distance a, Distance b)
{
    return Distance{ a.metres + b.metres };
}

constexpr std::uint64_t operator""_kb(unsigned long long value)
{
    return value * 1024;
}

constexpr std::uint64_t operator""_mb(unsigned long long value)
{
    return value * 1024 * 1024;
}

unitTests:
static_assert((250_m).metres == 250.0);
static_assert((2.5_m).metres == 2.5);
static_assert((3_km).metres == 3000.0);
static_assert((1.5_km + 250_m).metres == 1750.0, "literals and operator+ must be constexpr");
static_assert(4_kb == 4096);
static_assert(2_mb == 2097152);
static_assert(std::same_as<decltype(1_kb), std::uint64_t>);

TEST("distances") { const Distance trip{ 42_km + 195_m }; CHECK_NEAR(trip.metres, 42195.0, 1e-9); CHECK_NEAR((0.5_km).metres, 500.0, 1e-9); }
TEST("sizes") { CHECK_EQ(16_kb, 16384u); CHECK_EQ(1_mb, 1024_kb); CHECK_EQ(4096_mb, 4294967296ull); }

